void hid_process_field(struct hid_device *hid, struct hid_field *field, __u8 *data, int interrupt)
{
    int i;
    __s32 *value = kzalloc(field->maxusage * sizeof(__s32), GFP_KERNEL);

    for (i = 0; i < field->maxusage; i++) {
        __s32 val = hid->ll_driver->report_raw_value(hid, field, i, data);
        if (val < field->logical_minimum || val > field->logical_maximum)
            continue;

        if (field->usage[i].hid) {
            hid_process_event(hid, field, i, val);
        }

        field->value[i] = val;
    }

    kfree(value);
}

void process_hid_field(struct hid_device *hid, struct hid_field *field, __u8 *data, int interrupt)
{
    int i;
    struct hid_value *values = kmalloc(field->maxusage * sizeof(struct hid_value), GFP_KERNEL);

    for (i = 0; i < field->maxusage; i++) {
        struct hid_value *value = &values[i];
        __s32 val = hid->ll_driver->get_value(hid, field, data, i, 0);

        if (val < field->logical_minimum || val > field->logical_maximum)
            continue;

        if (field->flags & HID_MAIN_ITEM_CONSTANT)
            continue;

        hid_process_event(hid, field->report_type, field->usage[i], val);
    }

    for (i = 0; i < field->maxusage; i++)
        field->value[i] = values[i];

    kfree(values);
}

void hid_process_field(struct hid_device *hid, struct hid_field *field, __u8 *data, int interrupt)
{
    int i;
    __s32 *value = kmalloc(field->report_count * sizeof(__s32), GFP_KERNEL);
    if (!value)
        return;

    for (i = 0; i < field->report_count; i++) {
        __s32 v = hid_field->value[i];
        if (v < field->logical_minimum || v > field->logical_maximum)
            continue;

        if (field->flags & HID_ITEM_REL) {
            v = value[i] - hid_field->value[i];
            if (abs(v) < field->logical_minimum)
                continue;
        }

        hid_process_event(hid, field->usage[i].hid, v, interrupt);
    }

    memcpy(hid_field->value, value, field->report_count * sizeof(__s32));
    kfree(value);
}

void process_hid_field(struct hid_device *hid, struct hid_field *field, __u8 *data, int interrupt)
{
    int i;
    int *value = kmalloc(field->maxusage * sizeof(int), GFP_KERNEL);

    for (i = 0; i < field->maxusage; i++) {
        int logical = hid->ll_driver->get_value(hid, field, i, data);
        int min = field->logical_minimum;
        int max = field->logical_maximum;

        if (logical >= min && logical <= max) {
            hid_process_event(hid, field, i, logical);
        }
    }

    memcpy(field->value, value, field->maxusage * sizeof(int));
    kfree(value);
}
